<?php
require __DIR__.'/../bootstrap.php'; ensure_cms_schema();$slug=trim((string)getv('slug',''));$st=db()->prepare("SELECT p.*,u.full_name author_name FROM cms_posts p LEFT JOIN users u ON u.id=p.author_id WHERE p.slug=? AND p.post_type='page' AND p.status='published' AND p.visibility='public' LIMIT 1");$st->execute([$slug]);$page=$st->fetch();if(!$page){render_http_error_page(404,'Page not found','This page may have moved or is no longer available.');exit; }$title=$page['title'];public_header($title);?><article class="about-section cms-public-post <?=e($page['content_style']?:'default')?>" style="padding-block:<?=($page['vertical_padding']==='compact'?'24px':($page['vertical_padding']==='spacious'?'80px':'48px'))?>"><div class="eyebrow">PAGE</div><?php if(!empty($page['display_title'])):?><h1><?=e($page['title'])?></h1><?php endif;?><?php if(!empty($page['featured_image_url'])):?><img class="cms-featured-image" src="<?=e($page['featured_image_url'])?>" alt="<?=e($page['title'])?>"><?php endif;?><div class="cms-content"><?=$page['content']?></div></article><?php public_footer();
